INSERT INTO `methods_terms` (`key`, `group_key`, `name`, `position`, `public_description`, `rev`, `updated_seq`) VALUES
('source_kind.primary', 'source_kind', 'Primary', 0, 'Original material from the time and place it describes, such as a document, message, or log.', 1, 0),
('source_kind.secondary', 'source_kind', 'Secondary', 1, 'Material that reports on, analyses, or reproduces primary material, such as a book or article.', 1, 0),
('disclosure_level.public', 'disclosure_level', 'Public', 2, 'The material is published in this archive.', 1, 0),
('disclosure_level.withheld', 'disclosure_level', 'Withheld', 3, 'The archive records that the material exists, with its kind, date, and parties, but does not publish its content.', 1, 0),
('label_kind.quote', 'label_kind', 'Quote', 4, 'The exact words of the named source, reproduced without change.', 1, 0),
('label_kind.paraphrase', 'label_kind', 'Paraphrase', 5, 'The named source’s meaning in different words; it is not an exact quotation.', 1, 0),
('label_kind.source_reported', 'label_kind', 'Source-reported', 6, 'A claim as a source reports it, which the authors have not confirmed themselves.', 1, 0),
('term.scope_caveat', 'term', 'Scope caveat', 7, 'The limits within which a finding holds, such as the material or settings it covers.', 1, 0),
('term.elimination_scope', 'term', 'Elimination scope', 8, 'What exactly the evidence rules out when a hypothesis is eliminated, and what it leaves open.', 1, 0),
('term.resume_point', 'term', 'Resume point', 9, 'Where an unfinished run can continue from without repeating work.', 1, 0),
('term.withdrawn', 'term', 'Withdrawn', 10, 'The authors withdrew the material. It stays in the record, with the date and reason, so that nothing is silently removed.', 1, 0),
('term.superseded', 'term', 'Superseded', 11, 'A newer version replaces this one. The older version stays available and links to its successor.', 1, 0);
