INSERT INTO `policy_sections` (`page_key`, `section_key`, `position`, `title`, `required`, `text`, `text_spans`, `changed_at`) VALUES
('about', 'about_the_group', 0, 'About the group', 1, 'This archive is kept by the research group that runs this site. Its Administrators describe here who the group is, what it works on, and how it organises its work.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('people', 'introduction', 0, 'Introduction', 0, '', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('methods', 'evidence_standards', 0, 'Evidence standards', 1, 'Each finding states its claim, the limits within which it holds, and the evidence linked to it. A finding is marked confirmed only when that evidence supports it.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('methods', 'provenance_labels', 1, 'Provenance labels', 1, 'Exact quotations, paraphrases, and claims reported by a source are labelled separately and name their source, so that a reader can tell them apart from the authors’ own words.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('methods', 'statuses_and_outcomes', 2, 'Statuses and outcomes', 1, 'Records carry a status or outcome from the lists below. Negative results, eliminated hypotheses, and dead ends stay in the archive as part of the historical record.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('methods', 'withheld_and_private_material', 3, 'Withheld and private material', 1, 'Some material is withheld: the archive records that it exists, with its kind, date, and parties, but does not publish its content. Other material is not published at all, for example because consent or reproduction rights are missing.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('methods', 'corrections_and_withdrawals', 4, 'Corrections and withdrawals', 1, 'Corrections are recorded with a reason and a date. Withdrawn material stays in the record, marked with the date and reason, so that nothing is silently removed.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('licence', 'further_notes', 0, 'Further notes', 0, '', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('privacy', 'members', 0, 'Members', 1, 'For each Member the site keeps an email address for sign-in and notifications, the profile the Member enters, and a record of the Member’s contributions and their history, so that work stays attributed to its authors.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('privacy', 'submitters_and_requesters', 1, 'Submitters and requesters', 1, 'When someone uses the public form, the site keeps the name, email address, affiliation, message, and files they send, so that the group can review the submission, reply, and credit accepted material. The table below states how long each part is kept.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('privacy', 'people_named_in_records', 2, 'People named in records', 1, 'Research records can name people outside the group, such as correspondents and archive staff. Correspondence is published only with the consent of every outside party, and a person can be shown under a generic label instead of their name.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('privacy', 'visitors', 3, 'Visitors', 1, 'Reading the public archive needs no account, and the archive sets no cookies. The public form uses a bot check, and the site counts form use per network address for a short time to limit abuse.', '[]', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
('privacy', 'services_that_process_data', 4, 'Services that process data', 1, 'The software runs on Cloudflare. Cloudflare Workers, D1, and R2 store and serve the archive and the workspace, Cloudflare Access handles Member sign-in, and Cloudflare Turnstile checks that the public form is used by a person.
